package com.bds.admin.controller;

import com.bds.admin.dto.UpdateAuthUserRoleRequest;
import com.bds.admin.dto.UpdateAuthUserStatusRequest;
import com.bds.admin.dto.UpdateUserLabelRequest;
import com.bds.admin.service.AdminService;
import com.bds.common.Result;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/admin")
public class AdminController {
	private final AdminService adminService;

	public AdminController(AdminService adminService) {
		this.adminService = adminService;
	}

	@PutMapping("/users/{id}/label")
	public Result<Void> updateUserLabel(@PathVariable("id") String userId,
									@RequestBody UpdateUserLabelRequest request) {
		request.setUserId(userId);
		adminService.updateUserLabel(request);
		return Result.success(null);
	}

	@PutMapping("/auth-users/{id}/role")
	public Result<Void> updateAuthUserRole(@PathVariable("id") String userId,
											@RequestBody UpdateAuthUserRoleRequest request) {
		request.setUserId(userId);
		adminService.updateAuthUserRole(request);
		return Result.success(null);
	}

	@PutMapping("/auth-users/{id}/status")
	public Result<Void> updateAuthUserStatus(@PathVariable("id") String userId,
												@RequestBody UpdateAuthUserStatusRequest request) {
		request.setUserId(userId);
		adminService.updateAuthUserStatus(request);
		return Result.success(null);
	}
}

package com.bds.admin.dto;

import lombok.Data;

@Data
public class UpdateAuthUserRoleRequest {
	private String userId;
	private String role;
}

package com.bds.admin.dto;

import lombok.Data;

@Data
public class UpdateAuthUserStatusRequest {
	private String userId;
	private Integer status;
}

package com.bds.admin.dto;

import lombok.Data;

@Data
public class UpdateUserLabelRequest {
	private String userId;
	private Boolean isMalicious;
	private Double malProb;
}

package com.bds.auth.controller;

import com.bds.auth.dto.AuthUserProfileResponse;
import com.bds.auth.dto.LoginRequest;
import com.bds.auth.dto.RegisterRequest;
import com.bds.auth.dto.TokenResponse;
import com.bds.auth.service.AuthService;
import com.bds.common.Result;
import jakarta.validation.Valid;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/auth")
public class AuthController {
	private final AuthService authService;

	public AuthController(AuthService authService) {
		this.authService = authService;
	}

	@PostMapping("/login")
	public Result<TokenResponse> login(@Valid @RequestBody LoginRequest request) {
		return Result.success(authService.login(request));
	}

	@PostMapping("/register")
	public Result<TokenResponse> register(@Valid @RequestBody RegisterRequest request) {
		return Result.success(authService.register(request));
	}

	@GetMapping("/me")
	public Result<AuthUserProfileResponse> me() {
		return Result.success(authService.getCurrentUserProfile());
	}
}

package com.bds.auth.dto;

import lombok.AllArgsConstructor;
import lombok.Data;

@Data
@AllArgsConstructor
public class AuthUserProfileResponse {
	private String id;
	private String username;
	private String role;
	private Integer status;
}
